import collections

def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"

    n, m = map(int, lines[0].split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines) and lines[i]:
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)

    # Find connected components and their sizes
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                size += 1
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            component_sizes.append(size)

    # Check if any component is already lucky
    def is_lucky(num):
        for c in str(num):
            if c not in ('4', '7'):
                return False
        return True

    if any(is_lucky(size) for size in component_sizes):
        return "0\n"

    # Generate lucky numbers up to n
    lucky_numbers = []
    def generate_lucky(current):
        if current > n:
            return
        if current > 0:
            lucky_numbers.append(current)
        generate_lucky(current * 10 + 4)
        generate_lucky(current * 10 + 7)

    generate_lucky(4)
    generate_lucky(7)

    # Sort component sizes in descending order
    component_sizes.sort(reverse=True)

    # Use knapsack-like DP to find minimum components needed for each lucky number
    dp = {}

    for size in component_sizes:
        new_dp = dp.copy()
        for target in dp:
            new_dp[target + size] = min(new_dp.get(target + size, float('inf')), dp[target] + 1)
        new_dp[size] = min(new_dp.get(size, float('inf')), 1)
        new_dp[target + size] = min(new_dp.get(target + size, float('inf')), dp[target] + 1)
        dp = new_dp

    if not dp:
        return "-1\n"

    # Find minimum components among all lucky targets
    best_k = float('inf')

    for target in dp:
        if is_lucky(target):
            best_k = min(best_k, dp[target])

    if best_k == float('inf'):
        return "-1\n"

    # Minimum roads needed is (k-1) for k components
    return str(best_k - 1) + "\n"

