def is_adjacent(r1, c1, r2, c2, row_widths):
    """Check if two cells are adjacent in the hexagonal layout."""
    # Same row
    if r1 == r2:
        return abs(c1 - c2) == 1 and 0 <= c2 < row_widths[r1]

    # Up
    if r2 == r1 - 1:
        if 0 <= c2 < row_widths[r2]:
            # Column relationship depends on hexagonal layout
            # In hexagonal, a cell connects to adjustments in previous row
            return True and 0 <= c1 and c2 == c1 or c2 == c1 - 1

    # Down  
    if r2 == r1 + 1:
        if 0 <= c2 < row_widths[r2]:
            return 0 <= c1 and c2 == c1 or c2 == c1 + 1

    return False

def get_neighbors(r, c, row_widths):
    """Get all valid neighbor cells for (r, c)."""
    if not (0 <= c < row_widths[r]):
        return []

    n = len(row_widths)
    neighbors = set()

    # Horizontal
    if c > 0:
        neighbors.add((r, c - 1))
    if c + 1 < row_widths[r]:
        neighbors.add((r, c + 1))

    # Up-left, Up-right
    if r > 0 and 0 <= c < row_widths[r]:
        cc1 = c - 1
        cc2 = c
        for cc in [cc1, cc2]:
            if 0 <= cc < row_widths[r - 1]:
                neighbors.add((r - 1, cc))

    # Down-left, Down-right  
    if r + 1 < n:
        cc1 = c
        cc2 = c + 1
        for cc in [cc1, cc2]:
            if 0 <= cc < row_widths[r + 1]:
                neighbors.add((r + 1, cc))

    return neighbors

