def win_state(board):
    """Return True if current player can win from this board state."""
    chocolates = [(r, c) for r in range(len(board)) 
                  for c in range(len(board[r])) if board[r][c] == 'O']

    if not chocolates:
        return False  # No moves, current player loses

    # Try all possible moves - any connected subset of 2+ chocolates
    # in any direction
    first_moves = True
    winning_move_exists = False

    for r, c in chocolates:
        neighbors = get_neighbors(r, c, [len(row) for row in board])

        # Try extracting line in different directions from this cell
        directions = []
        if (r, c-1) in neighbors: directions.append((0, -1))
        if (r, c+1) in neighbors: directions.append((0, 1))
        if (r-1, max(0, c-1)) in neighbors: directions.append((-1, min(0, c)))
        if (r-1, min(len(board[r-1])-1, c)) in neighbors: directions.append((-1, max(0, c-1)))
        if (r+1, max(0, c)) in neighbors: directions.append((1, min(0, c)))
        if (r+1, min(len(board[r+1])-1, c+1)) in neighbors: directions.append((1, max(0, c)))

        for dr, dc in directions:
            line = [(r, c)]
            pr, pc = r + dr, c + dc
            while True:
                if pr >= len(board) or pr < 0:
                    break
                if pc >= len(board[pr]) or pc < 0:
                    break
                if board[pr][pc] == 'O':
                    line.append((pr, pc))
                else:
                    break
                pr += dr
                pc += dc

            if len(line) >= 2:
                # Valid move found
                new_board = [list(row) for row in board]
                for rr, rr_c in line:
                    new_board[rr][rr_c] = '.'
                new_board = tuple(tuple(row) for row in new_board)

                if not win_state(new_board):
                    winning_move_exists = True
                    break

        if winning_move_exists:
            break

    return winning_move_exists

