def solution(input_str):
    """
    Solves the tree component product problem.
    Parses input string and returns the maximum product of sizes of connected components.
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n = int(lines[0])

    if n <= 1:
        return '1'

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, n):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # DFS with memoization
    # dp[size] = {max product of all completed components in subtree}
    # where 'size' is the component containing the subtree root
    memo = {}

    def dfs(u, p):
        dp = {1: 1}  # Just u alone, size 1, other completed components product = 1

        for v in adj[u]:
            if v == p:
                continue

            child_dp = dfs(v, u)
            new_dp = {}

            for size_u, prod_u in dp.items():
                for size_v, prod_v in child_dp.items():
                    # Option 1: Cut edge (v's component becomes complete)
                    prod_cut = prod_u * prod_v * size_v
                    if size_u not in new_dp or prod_cut > new_dp[size_u]:
                        new_dp[size_u] = prod_cut

                    # Option 2: Don't cut (merge v's component with u)
                    new_size = size_u + size_v
                    new_prod = prod_u * prod_v
                    if new_size not in new_dp or new_prod > new_dp[new_size]:
                        new_dp[new_size] = new_prod

            dp = new_dp

        return dp

    # Root the tree at node 1
    result_dp = dfs(1, 0)

    # Find maximum product (size includes the final component with root)
    answer = 1
    for size, prod in result_dp.items():
        answer = max(answer, prod * size)

    return str(answer)


