def binary_search(circles, n):
    """
    Use binary search to find the time when the last hole disappears.
    A hole exists if we have a non-trivial cycle in the intersection graph.
    """
    if n <= 2:
        return str(-1)

    # Binary search on the time T
    low = 0.0
    high = 400010  # Maximum possible time given coordinates
    ans = -1.0

    def has_hole(t):
        """
        Check if there is still a hole at time t.
        A hole exists if the union of circles has non-trivial topology (has a cycle).
        """
        if t <= 1e-9:
            return False

        # Build a graph of circle intersections
        # Nodes are circles, edges exist if circles overlap at time t
        adj = [[] for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                dist = math.hypot(circles[i][0] - circles[j][0], 
                                 circles[i][1] - circles[j][1])
                # Two circles overlap if dist < r1 + r2 = 2t
                radius_sum = 2 * t
                if dist < max(1e-9, radius_sum):
                    adj[i].append(j)
                    adj[j].append(i)

        # Check if there's any cycle using BFS for each component
        visited = [False] * n
        for start in range(n):
            if visited[start]:
                continue

            # BFS to check for cycles
            queue = [start]
            visited[start] = True
            parent = {start: -1}

            idx = 0
            while idx < len(queue):
                u = queue[idx]
                idx += 1

                for v in adj[u]:
                    if not visited[v]:
                        parent[v] = u
                        visited[v] = True
                        queue.append(v)
                    elif v != parent[u]:
                        # Found a cycle - this means there's a hole
                        return True
        return False

    # Binary search for the answer
    for _ in range(60):  # 60 iterations for sufficient precision
        mid = (low + high) / 2
        if has_hole(mid):
            low = mid
        else:
            ans = mid
            high = mid

