from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n = int(lines[0])
    students = lines[1:n+1]
    pseudonyms = lines[n+1:n+1+n]

    # Calculate LCP
    def common_prefix_len(s1, s2):
        length = min(len(s1), len(s2))
        for i in range(length):
            if s1[i] != s2[i]:
                return i
        return length

    # Build trie for students
    class TrieNode:
        def __init__(self):
            self.children = {}
            self.students = []  # List of student indices that end at this node

    root = TrieNode()

    for i, student in enumerate(students):
        node = root
        for c in student:
            if c not in node.children:
                node.children[c] = TrieNode()
            node = node.children[c]
        node.students.append(i)

    # Sort students in each node for consistent matching
    def sort_students_recursive(node):
        if node.students:
            node.students.sort()
        for child in node.children.values():
