MOD = 10**9 + 7

def solution(s):
    s = s.strip()

    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0

        def peek(self):
            if self.pos < len(self.s):
                return self.s[self.pos]
            return None

        def advance(self):
            c = self.s[self.pos]
            self.pos += 1
            return c

        def parse(self):
            return self.parse_expression()

        def parse_expression(self):
            """expression ::= term | expression '+' term"""
            total_len = 0
            total_val = 0

            while True:
                term_res = self.parse_term()
                if total_len == 0:
                    total_len = term_res[0]
                    total_val = term_res[1]

                if self.peek() == '+':
                    self.advance()
                    term_res = self.parse_term()
                    total_len += term_res[0]
                    total_val = (total_val * pow(10, term_res[0], MOD) + term_res[1]) % MOD
                else:
                    return (total_len, total_val)

        def parse_term(self):
            """term ::= number | number '-' number | number '(' expression ')'"""
            l_val, l_len = self.parse_number()

            if self.peek() == '-':
                self.advance()  # consume '-'
                r_val, r_len = self.parse_number()
                return self.concat_range(l_val, r_val)
            elif self.peek() == '(':
                self.advance()  # consume '('
                inner_res = self.parse_expression()
                if self.peek() == ')':
                    self.advance()

                res_len, res_val = inner_res
                if l_len == 1 and 1 <= l_val <= 9:
                    n = l_val
                    # Concatenate inner result, n times
                    total_len, total_val = 0, 0
                    for _ in range(n):
                        total_len += res_len
                        total_val = (total_val * pow(10, res_len, MOD) + res_val) % MOD
                    return (total_len, total_val)
                else:
                    # Complex inner, multiply by using len(str(l_val))
                    num_digits = len(str(l_val))
                    total_len, total_val = 0, 0
                    for _ in range(n):
                        total_len += num_digits
                        total_val = (total_val + num_digits) % MOD
                    return (total_len, total_val)

            else:
                return (l_len, l_val)

        def parse_number(self):
            """number ::= pos_digit | number digit"""
            if not self.peek() or not (ord(self.peek()) >= ord('0') and ord(self.peek()) <= ord('9')):
                return (0, 0)

            start_len, start_val = 1, ord(self.peek()) - ord('0')
            self.advance()

            total_len, total_val = start_len, start_val

            while self.peek() and (ord(self.peek()) >= ord('0') and ord(self.peek()) <= ord('9')):
                total_len += 1
                total_val = (total_val * 10 + (ord(self.peek()) - ord('0'))) % MOD
                self.advance()

            return (total_len, total_val)

        def concat_range(self, l_val, r_val):
            """Concatenate all numbers from l to r"""
            if l_val > r_val:
                return (0, 0)

            total_len, total_val, i = 0, 0, l_val

            # Handle vector of numbers
            while i <= r_val:
                digits = 0
                for _ in range(10):
                    digits += 1
                    if i * (1 if digits == 1 else 0) > i:
                        break

                digit_len = len(str(i))
                total_len += digit_len
                total_val = (total_val * pow(10, digit_len, MOD) + i % MOD) % MOD
                i += 1

            return (total_len, total_val)

    result_len, result_val = Parser(s).parse()
    return str(result_val)

