def solution(input_str):
    """
    Solve the Turboplow Placement Problem.
    Place maximum number of T-shaped turboplows in an n x m grid.
    """
    import sys
    sys.setrecursionlimit(5000)

    n, m = map(int, input_str.strip().split())

    # If grid is too small for any T-piece
    if n < 3 or m < 3:
        return f"0\n" + '\n'.join(['.' * m for _ in range(n)])

    # Four T-piece patterns (relative positions from top-left corner)
    # P0: T pointing down (###\n.#\n.#)
    # P1: T pointing up   (..#\n###\n..#)  
    # P2: T pointing right (.#.\n..#\n###)
    # P3: T pointing left (#..\n###\n#..)
    pieces = [
        [(0, 0), (0, 1), (0, 2), (1, 1), (2, 1)],  # P0 - down
        [(0, 2), (1, 0), (1, 1), (1, 2), (2, 2)],  # P1 - up
        [(0, 1), (1, 1), (2, 0), (2, 1), (2, 2)],  # P2 - right
        [(0, 0), (1, 0), (1, 1), (1, 2), (2, 0)],  # P3 - left
    ]

    # Create grid
    grid = [['.' for _ in range(m)] for _ in range(n)]

    # Track best solution
    best_count = [0]
    best_grid = None

    def can_place(r, c, p):
        """Check if piece p fits at position (r, c)"""
        for dr, dc in p:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < n and 0 <= nc < m) or grid[nr][nc] != '.':
                return False
        return True

    def apply(r, c, p):
        """Place piece on grid"""
        for dr, dc in p:
            grid[r + dr][c + dc] = '#'

    def undo(r, c, p):
        """Remove piece from grid"""
        for dr, dc in p:
            grid[r + dr][c + dc] = '.'

    def solve(idx, placed, current_chars):
        """Backtracking solver"""
        if placed >= best_count[0] and placed >= len(current_chars):
            best_count[0] = placed
            best_grid = [row[:] for row in grid]
            return

        # Try to place a piece in next empty cell
        for cell_idx in range(n * m):
            r, c = cell_idx // m, cell_idx % m
            if grid[r][c] == '.':
                for i in range(len(pieces)):
                    if can_place(r, c, pieces[i]):
                        apply(r, c, pieces[i])
                        solve(
                            cell_idx + 1, placed + 1,
                            current_chars + [chr(ord('A') + placed)]
                        )
                        undo(r, c, pieces[i])

    if n * m == 0:
        return "0\n" + ''.join([''] * m)

    solve(0, 0, [])

    # Output result
    result = []
    result.append(str(best_count[0]))
    for row in best_grid:
        result.append(''.join(row))
    return '\n'.join(result)


