import math

class FenwickTree:
    def __init__(self, size):
        self.tree = [0.0] * (size + 1)
        self.size = size

    def update(self, i, value):
        while i <= self.size:
            if value > self.tree[i]:
                self.tree[i] = value
            i += i & (-i)

    def query(self, i):
        res = 0.0
        while i > 0:
            if self.tree[i] > res:
                res = self.tree[i]
            i -= i & (-i)
        return res

